export const getCellStyle = (sheet: BaseSheet, r: number, c: number) => {
  if (sheet.config.style) {
    const extendSparse = new BaseExtendSparse(sheet.config.style);
    return extendSparse.getCell(r, c);
  }
  return undefined;
};
